use super::*;
use photocraft_engine::doc::{Affine, AlphaChannel, BlendMode, Document, Layer, LayerContent, LayerId, LayerMask, Metadata, PixelFormat, Rect, SampleType, Slice, SliceOrigin, SmartFilter, SmartObject, SmartSource};
use photocraft_raster::Surface;
use std::{io::Read, path::PathBuf, sync::{Arc, Weak, atomic::{AtomicBool, Ordering}}};

pub(super) const APPLY: [&str;2] = ["edit.transform.warp", "layer.smartObjects.warp"];
pub(super) const MESH: [&str;5] = ["edit.transform.splitWarpCrosswise", "edit.transform.splitWarpHorizontally", "edit.transform.splitWarpVertically", "edit.transform.removeWarpSplit", "edit.transform.warpGrid"];
pub(super) struct Directory(pub(super) PathBuf);
impl Drop for Directory { fn drop(&mut self) { let _=std::fs::remove_dir_all(&self.0); } }
fn directory()->Directory { let path=std::env::temp_dir().join(format!("linked-warp-{}",ulid::Ulid::new()));std::fs::create_dir_all(&path).unwrap();Directory(path) }
pub(super) fn rgba()->Vec<u8> { vec![255,0,0,255,0,255,0,255,0,0,255,255,255,255,255,255] }
pub(super) fn encoded(format:&str,pixels:Vec<u8>)->Vec<u8> {
    match format {
        "png"=>{let image=photocraft_codecs::Image::from_u8(2,2,photocraft_codecs::ChannelLayout::Rgba,pixels).unwrap();photocraft_codecs::encode(&image,photocraft_codecs::Format::Png,&Default::default()).unwrap()},
        "psd"|"psb"=>{use photocraft_psd::{Compression,LayerSpec,PixelData,PsdBuilder,Version};let mut builder=PsdBuilder::new(2,2).version(if format=="psb"{Version::Psb}else{Version::Psd}).compression(Compression::Raw);builder.push_layer(LayerSpec::new("Known",0,0,2,2,PixelData::Rgba8(pixels.clone())));builder.composite(PixelData::Rgba8(pixels));builder.to_bytes().unwrap()},
        "pcraft"=>photocraft_engine::smart_cmds::encode_source(&photocraft_io::import("source.png",&encoded("png",pixels)).unwrap().document).unwrap(),_=>unreachable!(),
    }
}
fn object_layer(name:&str,source:SmartSource,x:i32,y:i32,format:PixelFormat)->Layer {
    let mut cache=Surface::new(format);cache.fill_rect(Rect::from_xywh(x,y,1,1),&[0.25,0.5,0.75,1.]);
    let mut object=SmartObject::new(source,Affine::translate(f64::from(x),f64::from(y)),Some(cache));
    object.smart_filters=vec![SmartFilter{command:"filter.other.offset".into(),params:json!({"horizontal":1,"vertical":0,"undefinedAreas":"transparent","vendor":[null,7]}),visible:true,opacity:1.,blend:BlendMode::Normal},SmartFilter{command:"filter.cameraRaw".into(),params:json!({"exposure":2,"vendor":{"keep":true}}),visible:false,opacity:0.42,blend:BlendMode::Multiply}];
    let mut mask=LayerMask::hide_all();mask.surface.write_pixel(x,y,&[0.4]);mask.enabled=false;mask.linked=false;mask.density=0.42;mask.feather=1.25;object.filter_mask=Some(mask);object.psd_raw=Some(Arc::new(b"retained placed data".to_vec()));
    let mut layer=Layer::new(name,LayerContent::Smart(object));let mut mask=LayerMask::reveal_all();mask.linked=false;mask.density=0.6;layer.mask=Some(mask);
    for key in [*b"SoLd",*b"SoLE",*b"PlLd",*b"zzzz"]{layer.psd_blocks.push((key,Arc::new([key.as_slice(),b" retained"].concat())));}layer
}
pub(super) struct Fixture {
    pub(super) directory:Directory,pub(super) engine:Session,pub(super) active:LayerId,pub(super) other:LayerId,pub(super) embedded:LayerId,pub(super) group:LayerId,pub(super) raster:LayerId,pub(super) path:PathBuf,pub(super) bytes:Vec<u8>,
}
pub(super) fn fixture(depth:u32,format:&str)->Fixture {
    let directory=directory();let path=directory.0.join(format!("source.{format}"));let bytes=encoded(format,rgba());std::fs::write(&path,&bytes).unwrap();
    let mut engine=Session::new();engine.execute("file.new",json!({"width":16,"height":12,"depth":depth})).unwrap();let fmt=engine.active().unwrap().doc.pixel_format();
    let first=object_layer("Original Linked",SmartSource::Linked{path:path.to_string_lossy().into()},2,1,fmt);let mut other=object_layer("Repeated Linked",SmartSource::Linked{path:path.to_string_lossy().into()},8,1,fmt);other.visible=false;
    let embedded=object_layer("Embedded sibling",SmartSource::Embedded{file_name:format!("embedded.{format}"),bytes:Arc::new(bytes.clone())},2,6,fmt);let raster=Layer::raster("Raster sibling",fmt);let ids=[first.id,other.id,embedded.id,raster.id];let group=Layer::group("Nested group",vec![other,Layer::group("Inner group",vec![embedded,raster])]);let group_id=group.id;
    engine.edit("Warp fixture",|doc,current|{doc.layers=vec![first,group];*current=Some(ids[0]);let mut coverage=Surface::new(PixelFormat::GRAY8);coverage.fill_rect(Rect::new(2,1,3,2),&[0.5]);doc.selection=Some(coverage.clone());doc.channels.push(AlphaChannel::new("Retained Alpha",coverage.clone()));doc.quick_mask=Some(AlphaChannel::new("Quick Mask",coverage));doc.metadata.psd_global_blocks.push((*b"8BIM",*b"zzzz",Arc::new(b"unrelated globals".to_vec())));doc.slices.list=vec![Slice{id:1,origin:SliceOrigin::Layer,layer:Some(ids[0]),rect:Rect::from_xywh(2,1,1,1),..Default::default()}];Ok(())}).unwrap();normalize(&mut engine);
    let state=engine.active_mut().unwrap();state.selected_layers=vec![ids[0],ids[1]];state.layer_anchor=Some(ids[1]);state.channel_view.target=photocraft_engine::channel_cmds::ChannelTarget::Alpha(0);
    engine.tools.foreground=[0.2,0.3,0.4,0.5];engine.tools.background=[0.7,0.6,0.5,0.4];let state=engine.active().unwrap();engine.edit_state.fade=Some(photocraft_engine::edit_menu_cmds::FadeSource{doc:state.doc.id,revision:state.revision,layer:ids[0],mask:false,label:"Older Warp Fade".into()});
    Fixture{directory,engine,active:ids[0],other:ids[1],embedded:ids[2],group:group_id,raster:ids[3],path,bytes}
}
pub(super) fn normalize(engine:&mut Session){let index=engine.active_index().unwrap();engine.execute("document.activate",json!({"document":index})).unwrap();}
pub(super) fn smart(doc:&Document,id:LayerId)->&SmartObject{let LayerContent::Smart(object)=&doc.layer(id).unwrap().content else{panic!("Expected Smart Object")};object}
pub(super) fn twin(engine:&Session)->Session{let state=engine.active().unwrap();let mut copy=Session::new();copy.add_document(Document::new("Twin",state.doc.size,state.doc.mode,state.doc.depth),None);*copy.active_mut().unwrap()=state.clone();copy.journal=engine.journal.clone();copy.tools=engine.tools.clone();copy.presets=engine.presets.clone();copy.patterns=engine.patterns.clone();copy.clipboard=engine.clipboard.clone();copy.style_clipboard=engine.style_clipboard.clone();copy.edit_state=engine.edit_state.clone();super::super::super::color_views::Snapshot::capture(engine).unwrap().install(&mut copy).unwrap();copy}
pub(super) fn same(actual:&Session,native:&Session){let a=actual.active().unwrap();let n=native.active().unwrap();assert_eq!(a.doc,n.doc);assert_eq!(a.history.entries(),n.history.entries());assert_eq!(a.history.past_len(),n.history.past_len());for index in 0..a.history.past_len(){assert_eq!(a.history.state(index),n.history.state(index));}assert_eq!(a.history.redo_labels().collect::<Vec<_>>(),n.history.redo_labels().collect::<Vec<_>>());assert_eq!((a.revision,a.saved_revision,&a.coalesce,a.active_layer,&a.selected_layers,a.layer_anchor,&a.path,&a.last_damage),(n.revision,n.saved_revision,&n.coalesce,n.active_layer,&n.selected_layers,n.layer_anchor,&n.path,&n.last_damage));assert_eq!(a.channel_view,n.channel_view);assert_eq!(a.isolated_layers,n.isolated_layers);assert_eq!(a.fx_collapsed,n.fx_collapsed);assert_eq!(format!("{:?}",a.symmetry_path),format!("{:?}",n.symmetry_path));assert_eq!(actual.journal,native.journal);assert_eq!(actual.edit_state.fade,native.edit_state.fade);assert_eq!(actual.tools.foreground,native.tools.foreground);assert_eq!(actual.tools.background,native.tools.background);assert_eq!(actual.tools.brush,native.tools.brush);assert_eq!(actual.style_clipboard,native.style_clipboard);assert_eq!(format!("{:?}",actual.clipboard),format!("{:?}",native.clipboard));assert_eq!(super::super::super::tools::presets(actual),super::super::super::tools::presets(native));assert_eq!(super::super::super::color_views::key(actual).unwrap(),super::super::super::color_views::key(native).unwrap());}
pub(super) fn unchanged(engine:&Session,before:&Session){same(engine,before);assert!(Arc::ptr_eq(&engine.active().unwrap().doc,&before.active().unwrap().doc));}
pub(super) fn host(engine:&mut Session,command:&str,params:Value)->Result<Value,String>{super::super::super::execute_view_command(engine,command,params)}
pub(super) fn checked(_:LayerId,meta:&Metadata,object:&SmartObject)->Result<Option<super::super::Bytes>,String>{super::super::super::smart::source_bytes_checked(meta,&object.source,||Ok(()))}
pub(super) fn translated()->Value{translated_over([2,1,4,3])}
fn translated_over(rect:[i32;4])->Value{let mut points=Vec::new();for j in 0..4{for i in 0..4{points.push([f64::from(rect[0])+3.+f64::from(rect[2]-rect[0])*f64::from(i)/3.,f64::from(rect[1])+2.+f64::from(rect[3]-rect[1])*f64::from(j)/3.]);}}json!({"rect":rect,"mesh":{"us":[0,1],"vs":[0,1],"points":points},"interpolation":"nearest"})}
pub(super) fn stored(engine:&mut Session,id:LayerId){let warp=photocraft_engine::warp_cmds::warp_from_params(APPLY[0],&json!({"style":"custom"}),[0.,0.,2.,2.]).unwrap();engine.edit("Stored identity Warp",|doc,_|{let LayerContent::Smart(object)=&mut doc.layer_mut(id).unwrap().content else{unreachable!()};object.warp=Some(warp);Ok(())}).unwrap();normalize(engine);}
fn retained(engine:&Session,before:&Document,id:LayerId){let doc=&engine.active().unwrap().doc;let a=smart(doc,id);let b=smart(before,id);assert_eq!(a.source,b.source);assert_eq!(a.transform,b.transform);assert_eq!(a.perspective,b.perspective);assert_eq!(a.psd_raw,b.psd_raw);assert_eq!(a.smart_filters,b.smart_filters);assert_eq!(doc.layer(id).unwrap().psd_blocks,before.layer(id).unwrap().psd_blocks);assert_eq!(doc.metadata,before.metadata);assert_eq!(doc.channels,before.channels);assert_eq!(doc.quick_mask,before.quick_mask);}
pub(super) fn pixels(engine:&Session,id:LayerId,rect:Rect,raw:&[u8]){let doc=&engine.active().unwrap().doc;let cache=smart(doc,id).cache.as_ref().unwrap();let tolerance=match doc.depth{SampleType::U8=>1./255.,SampleType::U16=>2./65535.,SampleType::F32=>1e-6};for y in -2..16{for x in -2..20{let expected=if rect.contains(x,y){let index=((y-rect.y0)*rect.width() as i32+x-rect.x0) as usize*4;[raw[index] as f32/255.,raw[index+1] as f32/255.,raw[index+2] as f32/255.,raw[index+3] as f32/255.]}else{[0.;4]};let actual=cache.pixel(x,y);for channel in 0..4{assert!((actual[channel]-expected[channel]).abs()<=tolerance,"{:?}/{x},{y}/{channel}:{} != {}",doc.depth,actual[channel],expected[channel]);}assert_eq!(actual[3],expected[3]);}}}
fn unsafe_filter()->SmartFilter{SmartFilter{command:"plugin.run".into(),params:json!({"path":"must never run"}),visible:true,opacity:0.,blend:BlendMode::Normal}}

#[test]
fn linked_warp_apply_two_ids_four_formats_three_depths_match_native_and_literal_affine_pixels(){
    for command in APPLY{for depth in [8,16,32]{for format in ["png","pcraft","psd","psb"]{let mut f=fixture(depth,format);let before=f.engine.active().unwrap().doc.clone();let past=f.engine.active().unwrap().history.past_len();let journal=f.engine.journal.len();let mut native=twin(&f.engine);let params=translated();assert_eq!(host(&mut f.engine,command,params.clone()).unwrap(),native.execute(command,params).unwrap());same(&f.engine,&native);retained(&f.engine,&before,f.active);pixels(&f.engine,f.active,Rect::new(6,3,8,5),&rgba());assert_eq!(f.engine.active().unwrap().doc.layer(f.group),before.layer(f.group));assert_eq!(f.engine.active().unwrap().history.past_len(),past+1);assert_eq!(f.engine.journal.len(),journal+1);let after=f.engine.active().unwrap().doc.clone();f.engine.execute("edit.undo",json!({})).unwrap();native.execute("edit.undo",json!({})).unwrap();same(&f.engine,&native);assert!(Arc::ptr_eq(&f.engine.active().unwrap().doc,&before));f.engine.execute("edit.redo",json!({})).unwrap();native.execute("edit.redo",json!({})).unwrap();same(&f.engine,&native);assert_eq!(f.engine.active().unwrap().doc,after);}}}
}

#[test]
fn linked_warp_apply_missing_corrupt_and_empty_uuid_metadata_keep_native_transformed_fallback(){
    use photocraft_io::linked::{encode_linked_file,LinkedFile};
    for failure in ["missing","corrupt"]{let mut f=fixture(16,"png");let id=f.active;f.engine.edit("Unsafe unavailable source",|doc,_|{let LayerContent::Smart(object)=&mut doc.layer_mut(id).unwrap().content else{unreachable!()};object.smart_filters.push(unsafe_filter());doc.metadata.psd_global_blocks.push((*b"8BIM",*b"lnk2",Arc::new(encode_linked_file(&LinkedFile{uuid:String::new(),file_name:"unrelated.png".into(),bytes:encoded("png",[255,255,0,255].repeat(4))}))));Ok(())}).unwrap();normalize(&mut f.engine);if failure=="missing"{std::fs::remove_file(&f.path).unwrap();}else{std::fs::write(&f.path,b"undecodable Warp source").unwrap();}let before=f.engine.active().unwrap().doc.clone();let mut native=twin(&f.engine);let params=translated();assert_eq!(host(&mut f.engine,APPLY[0],params.clone()).unwrap(),native.execute(APPLY[0],params).unwrap());same(&f.engine,&native);retained(&f.engine,&before,id);let cache=smart(&f.engine.active().unwrap().doc,id).cache.as_ref().unwrap();for y in 0..12{for x in 0..16{let expected=if(x,y)==(5,3){[0.25,0.5,0.75,1.]}else{[0.;4]};let actual=cache.pixel(x,y);for channel in 0..4{assert!((actual[channel]-expected[channel]).abs()<=2./65535.);}assert_eq!(actual[3],expected[3]);}}}
}

#[test]
fn linked_warp_apply_nested_groups_resolve_each_occurrence_in_order_and_retire_pins(){
    let mut f=fixture(16,"png");let id=f.active;let group=f.group;f.engine.edit("Group Warp scope",|doc,active|{let first=doc.remove(id).unwrap();doc.layer_mut(group).unwrap().children_mut().unwrap().insert(0,first);*active=Some(group);Ok(())}).unwrap();normalize(&mut f.engine);
    let before=f.engine.active().unwrap().doc.clone();let mut native=twin(&f.engine);let mut params=translated_over([0,0,16,12]);params["layer"]=json!(group.0);let mut visits=Vec::new();let mut pins:Vec<Weak<Vec<u8>>>=Vec::new();
    assert_eq!(run_with(&mut f.engine,APPLY[0],&params,|id,meta,object|{assert!(pins.iter().all(|pin|pin.upgrade().is_none()));visits.push(id);assert_eq!(object.source,smart(&before,id).source);let bytes=checked(id,meta,object)?;if matches!(object.source,SmartSource::Linked{..}){pins.push(Arc::downgrade(&bytes.as_ref().unwrap().1));}Ok(bytes)}).unwrap(),native.execute(APPLY[0],params).unwrap());same(&f.engine,&native);assert_eq!(visits,vec![f.active,f.other,f.embedded]);assert!(pins.iter().all(|pin|pin.upgrade().is_none()));for(id,x,y)in[(f.active,6,3),(f.other,12,3),(f.embedded,6,8)]{pixels(&f.engine,id,Rect::from_xywh(x,y,2,2),&rgba());retained(&f.engine,&before,id);}
}

#[test]
fn linked_warp_apply_source_decision_survives_deletion_and_metadata_first_authority(){
    use photocraft_io::linked::{encode_linked_file,LinkedFile};
    let mut f=fixture(32,"psb");let before=f.engine.active().unwrap().doc.clone();let mut calls=0;run_with(&mut f.engine,APPLY[1],&translated(),|id,meta,object|{calls+=1;let source=checked(id,meta,object)?;std::fs::remove_file(&f.path).unwrap();Ok(source)}).unwrap();assert_eq!(calls,1);pixels(&f.engine,f.active,Rect::new(6,3,8,5),&rgba());retained(&f.engine,&before,f.active);
    let mut f=fixture(16,"png");let blue=[0,0,255,255].repeat(4);let mut block=encode_linked_file(&LinkedFile{uuid:f.path.to_string_lossy().into(),file_name:"authoritative.psb".into(),bytes:encoded("psb",blue.clone())});block.extend(encode_linked_file(&LinkedFile{uuid:f.path.to_string_lossy().into(),file_name:"ignored.png".into(),bytes:f.bytes.clone()}));f.engine.edit("Metadata Warp authority",|doc,_|{doc.metadata.psd_global_blocks.push((*b"8BIM",*b"lnk2",Arc::new(block)));Ok(())}).unwrap();normalize(&mut f.engine);std::fs::write(&f.path,b"unreadable donor content").unwrap();let before=f.engine.active().unwrap().doc.clone();let mut native=twin(&f.engine);let params=translated();assert_eq!(host(&mut f.engine,APPLY[0],params.clone()).unwrap(),native.execute(APPLY[0],params).unwrap());same(&f.engine,&native);pixels(&f.engine,f.active,Rect::new(6,3,8,5),&blue);retained(&f.engine,&before,f.active);
}

#[test]
fn linked_warp_stored_five_commands_match_native_and_exact_knots_at_three_depths(){
    for depth in [8,16,32]{for (index,command)in MESH.into_iter().enumerate(){let mut f=fixture(depth,"pcraft");stored(&mut f.engine,f.active);if index==3{host(&mut f.engine,MESH[0],json!({"at":[3,2]})).unwrap();}let before=f.engine.active().unwrap().doc.clone();let mut native=twin(&f.engine);let params=if index==4{json!({"size":4,"layer":f.other.0})}else if index==3{json!({"at":[3,1.9],"layer":f.other.0})}else{json!({"at":[3,2],"layer":f.other.0})};let mut reads=0;
        assert_eq!(mesh::run_with(&mut f.engine,command,&params,|meta,object|{reads+=1;assert!(object.warp.is_some());assert_eq!(object.source,smart(&before,f.active).source);checked(f.active,meta,object)}).unwrap(),native.execute(command,params).unwrap());assert_eq!(reads,1);same(&f.engine,&native);retained(&f.engine,&before,f.active);assert_eq!(f.engine.active().unwrap().doc.layer(f.other),before.layer(f.other));let warp=smart(&f.engine.active().unwrap().doc,f.active).warp.as_ref().unwrap();let mesh=warp.mesh.as_ref().unwrap();let thirds=vec![0.,1./3.,2./3.,1.];let split=vec![0.,1./3.,0.5,2./3.,1.];let grid=vec![0.,0.25,0.5,0.75,1.];let (u,v)=match index{0=>(split.clone(),split),1=>(thirds,split),2=>(split,thirds),3=>(vec![0.,1./3.,2./3.,1.],vec![0.,1./3.,0.5,2./3.,1.]),_=>(grid.clone(),grid)};assert_eq!(mesh.us,u);assert_eq!(mesh.vs,v);assert_eq!(warp.bounds,[0.,0.,2.,2.]);for(x,y)in[(0.,0.),(0.25,1.5),(1.,1.),(2.,2.)]{let actual=warp.map(x,y);assert!((actual.0-x).abs()<1e-10);assert!((actual.1-y).abs()<1e-10);}assert_eq!(f.engine.active().unwrap().doc.selection,before.selection);
    }}
}

#[test]
fn linked_warp_inline_mesh_commands_return_exact_geometry_without_source_history_or_document_change(){
    for(index,command)in MESH.into_iter().enumerate(){let mut f=fixture(16,"png");std::fs::OpenOptions::new().write(true).open(&f.path).unwrap().set_len(super::super::super::MAX_INPUT_BYTES+1).unwrap();let mut params=translated();params["at"]=json!([6,4]);if index==4{params["size"]=json!(3);}if index==3{let split=f.engine.execute(MESH[0],params.clone()).unwrap();params=json!({"warp":split["warp"],"at":[6,4]});}let before=twin(&f.engine);let mut native=twin(&f.engine);let past=f.engine.active().unwrap().history.past_len();let revision=f.engine.active().unwrap().revision;let mut calls=0;
        let result=mesh::run_with(&mut f.engine,command,&params,|_,_|{calls+=1;panic!("Inline Warp read a source")}).unwrap();assert_eq!(result,native.execute(command,params).unwrap());assert_eq!(calls,0);same(&f.engine,&native);assert!(Arc::ptr_eq(&f.engine.active().unwrap().doc,&before.active().unwrap().doc));assert_eq!(f.engine.active().unwrap().history.past_len(),past);assert_eq!(f.engine.active().unwrap().revision,revision);assert_eq!(f.engine.journal.len(),before.journal.len()+1);
        let out=photocraft_engine::warp_cmds::warp_from_params(command,&json!({"warp":result["warp"]}),[0.;4]).unwrap();for(x,y)in[(2.,1.),(2.4,1.7),(4.,3.)]{let actual=out.map(x,y);assert!((actual.0-(x+3.)).abs()<1e-9);assert!((actual.1-(y+2.)).abs()<1e-9);}let mesh=out.mesh.unwrap();if index==4{assert_eq!(mesh.us,vec![0.,1./3.,2./3.,1.]);assert_eq!(mesh.vs,mesh.us);}else{assert!(mesh.us.len()>=4&&mesh.vs.len()>=4);}
    }
    let mut f=fixture(32,"png");let before=f.engine.active().unwrap().doc.clone();let mut native=twin(&f.engine);let mut params=translated();params["mesh"]["points"][15][0]=json!(7.4);params["size"]=json!(4);let result=host(&mut f.engine,MESH[4],params.clone()).unwrap();assert_eq!(result,native.execute(MESH[4],params).unwrap());same(&f.engine,&native);assert!(Arc::ptr_eq(&f.engine.active().unwrap().doc,&before));let out=photocraft_engine::warp_cmds::warp_from_params(MESH[4],&json!({"warp":result["warp"]}),[0.;4]).unwrap();assert_eq!(out.mesh.as_ref().unwrap().us,vec![0.,0.25,0.5,0.75,1.]);for(s,t)in[(0.,0.),(0.17,0.63),(0.5,0.5),(1.,1.)]{let(x,y)=(2.+2.*s,1.+2.*t);let actual=out.map(x,y);let expected=x+3.+0.4*s*s*s*t*t*t;assert!((actual.0-expected).abs()<1e-10);assert!((actual.1-(y+2.)).abs()<1e-10);}
}

#[test]
fn linked_warp_stored_default_source_bounds_preserve_split_two_corner_and_grid_four_corner_rules(){
    for command in [MESH[0],MESH[4]]{let mut f=fixture(32,"png");let id=f.active;f.engine.edit("Projective Warp frame",|doc,_|{let LayerContent::Smart(object)=&mut doc.layer_mut(id).unwrap().content else{unreachable!()};object.perspective=Some([1.,-1.,2.,1.,1.,1.,0.1,0.,1.]);Ok(())}).unwrap();normalize(&mut f.engine);let mut native=twin(&f.engine);let params=if command==MESH[4]{json!({"size":"default"})}else{json!({})};assert_eq!(host(&mut f.engine,command,params.clone()).unwrap(),native.execute(command,params).unwrap());same(&f.engine,&native);let bounds=smart(&f.engine.active().unwrap().doc,id).warp.as_ref().unwrap().bounds;let expected=if command==MESH[4]{[0.,-0.5625,4./3.,0.5]}else{[0.,-1./15.,4./3.,0.]};for axis in 0..4{assert!((bounds[axis]-expected[axis]).abs()<1e-12,"{command}/{axis}:{} != {}",bounds[axis],expected[axis]);}}
}

#[test]
fn linked_warp_stored_missing_source_commits_but_corrupt_and_unsafe_available_sources_refuse_atomically(){
    for failure in ["missing","corrupt","unsafe"]{for command in MESH{let mut f=fixture(16,"png");stored(&mut f.engine,f.active);if command==MESH[3]{host(&mut f.engine,MESH[0],json!({})).unwrap();}let id=f.active;f.engine.edit("Source refusal Warp",|doc,_|{let LayerContent::Smart(object)=&mut doc.layer_mut(id).unwrap().content else{unreachable!()};object.smart_filters.push(unsafe_filter());Ok(())}).unwrap();normalize(&mut f.engine);if failure=="missing"{std::fs::remove_file(&f.path).unwrap();}else if failure=="corrupt"{std::fs::write(&f.path,b"bad stored Warp source").unwrap();}let before=twin(&f.engine);let mut native=twin(&f.engine);let params=if command==MESH[4]{json!({"size":3})}else{json!({"at":[3,2]})};let actual=host(&mut f.engine,command,params.clone());if failure=="unsafe"{assert!(actual.unwrap_err().contains("does not support"));unchanged(&f.engine,&before);}else{let expected=native.execute(command,params);if failure=="missing"{assert_eq!(actual.unwrap(),expected.unwrap());same(&f.engine,&native);assert_eq!(smart(&f.engine.active().unwrap().doc,id).cache,smart(&before.active().unwrap().doc,id).cache);}else{assert_eq!(actual.unwrap_err(),expected.unwrap_err().to_string());unchanged(&f.engine,&before);}}}}
}

#[test]
fn linked_warp_late_group_limits_growing_readers_and_panics_leave_authoritative_state_unchanged(){
    for failure in ["lateCap","growing","panic"]{let mut f=fixture(16,"png");let id=f.active;let group=f.group;f.engine.edit("Group failure scope",|doc,active|{let first=doc.remove(id).unwrap();doc.layer_mut(group).unwrap().children_mut().unwrap().insert(0,first);*active=Some(group);Ok(())}).unwrap();normalize(&mut f.engine);let before=twin(&f.engine);let mut visits=Vec::new();let mut params=translated_over([0,0,16,12]);params["layer"]=json!(group.0);let error=run_with(&mut f.engine,APPLY[0],&params,|id,meta,object|{visits.push(id);if visits.len()==1{return checked(id,meta,object);}if failure=="panic"{panic!("Injected Warp source panic");}if failure=="lateCap"{std::fs::OpenOptions::new().write(true).open(&f.path).unwrap().set_len(super::super::super::MAX_INPUT_BYTES+1).unwrap();return checked(id,meta,object);}struct Growing(usize);impl Read for Growing{fn read(&mut self,out:&mut[u8])->std::io::Result<usize>{self.0+=out.len();out.fill(7);Ok(out.len())}}let mut reader=Growing(0);let bytes=super::super::super::smart::replay_read_with_limit(&mut reader,32);assert_eq!(reader.0,33);bytes.map(|bytes|Some(("growth.png".into(),Arc::new(bytes))))}).unwrap_err();assert_eq!(visits,vec![f.active,f.other]);if failure=="panic"{assert!(error.contains(APPLY[0])&&error.contains("internal error"));}else{assert!(error.contains("512MB"));}unchanged(&f.engine,&before);}
}

#[test]
fn linked_warp_native_target_defaults_invalid_geometry_and_inline_validation_precede_source_reads(){
    for layer in [Value::Null,json!(-1),json!("invalid")]{let mut f=fixture(16,"png");let mut native=twin(&f.engine);let mut params=translated();params["layer"]=layer;assert_eq!(host(&mut f.engine,APPLY[1],params.clone()).unwrap(),native.execute(APPLY[1],params).unwrap());same(&f.engine,&native);pixels(&f.engine,f.active,Rect::new(6,3,8,5),&rgba());}
    for target in ["other","embedded"]{let mut f=fixture(16,"png");let id=if target=="other"{f.other}else{f.embedded};let before=f.engine.active().unwrap().doc.clone();let mut native=twin(&f.engine);let params=json!({"layer":id.0,"rect":[2,1,4,3],"style":"none"});assert_eq!(host(&mut f.engine,APPLY[1],params.clone()).unwrap(),native.execute(APPLY[1],params).unwrap());same(&f.engine,&native);assert_eq!(f.engine.active().unwrap().doc.layer(f.active),before.layer(f.active));}
    for case in ["stale","style","rect","mesh","locked","rasterIdentity","emptyBounds","activeRaster"]{let mut f=fixture(16,"png");let mut params=translated();match case{"stale"=>params["layer"]=json!(u64::MAX),"style"=>params=json!({"style":"notWarp"}),"rect"=>params["rect"]=json!([0,0,0,0]),"mesh"=>params["mesh"]=json!({"us":[0,1],"vs":[0,1],"points":[[0,0]]}),"locked"=>{let id=f.active;f.engine.edit("Locked Warp",|doc,_|{doc.layer_mut(id).unwrap().locks.all=true;Ok(())}).unwrap();},"rasterIdentity"=>{params=json!({"layer":f.raster.0,"rect":[0,0,2,2],"style":"none"});},"emptyBounds"=>params=json!({"layer":f.raster.0,"style":"none"}),_=>f.engine.active_mut().unwrap().active_layer=Some(f.raster)}let before=twin(&f.engine);let mut native=twin(&f.engine);let command=if case=="activeRaster"{APPLY[1]}else{APPLY[0]};let mut calls=0;let actual=run_with(&mut f.engine,command,&params,|_,_,_|{calls+=1;panic!("Invalid Warp read a source")});let expected=native.execute(command,params);if case=="emptyBounds"{assert!(actual.as_ref().unwrap_err().contains("nothing to warp"));}assert_eq!(actual,expected.map_err(|error|error.to_string()));assert_eq!(calls,0);same(&f.engine,&native);assert!(Arc::ptr_eq(&f.engine.active().unwrap().doc,&before.active().unwrap().doc));}
    for(command,params)in [(MESH[4],json!({"size":0})),(MESH[4],json!({"size":65})),(MESH[4],json!({"size":1.5})),(MESH[4],json!({"grid":[3,3]})),(MESH[4],json!({"size":3,"warp":null})),(MESH[0],json!({"warp":null})),(MESH[0],json!({"mesh":{"us":[0,1],"vs":[0,1],"points":[]}}))]{let mut f=fixture(16,"png");let before=twin(&f.engine);let mut native=twin(&f.engine);let mut calls=0;let actual=mesh::run_with(&mut f.engine,command,&params,|_,_|{calls+=1;panic!("Invalid mesh read a source")}).unwrap_err();assert_eq!(actual,native.execute(command,params).unwrap_err().to_string());assert_eq!(calls,0);unchanged(&f.engine,&before);}
    for command in [APPLY[0],APPLY[1],MESH[0],MESH[4]]{let mut engine=Session::new();let mut native=Session::new();let params=if command==MESH[4]{json!({"size":3})}else{translated()};assert_eq!(host(&mut engine,command,params.clone()).unwrap_err(),native.execute(command,params).unwrap_err().to_string());assert!(engine.active().is_none());assert!(engine.journal.is_empty());}
}

#[test]
fn linked_warp_apply_mask_alpha_and_quick_mask_parameters_still_route_to_actual_layer_pixels(){
    for target in [json!("mask"),json!({"channel":0}),json!("quickMask")]{let mut f=fixture(16,"png");let before=f.engine.active().unwrap().doc.clone();let mut native=twin(&f.engine);let mut params=translated();params["target"]=target;assert_eq!(host(&mut f.engine,APPLY[0],params.clone()).unwrap(),native.execute(APPLY[0],params).unwrap());same(&f.engine,&native);pixels(&f.engine,f.active,Rect::new(6,3,8,5),&rgba());assert_eq!(f.engine.active().unwrap().doc.channels,before.channels);assert_eq!(f.engine.active().unwrap().doc.quick_mask,before.quick_mask);assert_ne!(f.engine.active().unwrap().doc.selection,before.selection);}
}

#[test]
fn linked_warp_active_job_refusal_precedes_apply_and_stored_source_resolution(){
    struct Release(Arc<AtomicBool>);impl Drop for Release{fn drop(&mut self){self.0.store(true,Ordering::SeqCst);}}
    for command in [APPLY[0],MESH[4]]{let mut f=fixture(16,"png");let release=Arc::new(AtomicBool::new(false));let _release=Release(release.clone());let worker=release.clone();let started=f.engine.start_job("warp-test",json!({}),"Retained Warp job",true,move|context|{while !worker.load(Ordering::SeqCst){context.check()?;std::thread::yield_now();}Ok(())},|_,_|Ok(Value::Null)).unwrap();let photocraft_engine::jobs::Started::Job(job)=started else{panic!("Expected native job")};let before=twin(&f.engine);let params=if command==MESH[4]{json!({"size":3})}else{translated()};let expected=f.engine.disabled_reason(command).unwrap();let mut calls=0;let error=if command==MESH[4]{mesh::run_with(&mut f.engine,command,&params,|_,_|{calls+=1;panic!("Job refusal read source")}).unwrap_err()}else{run_with(&mut f.engine,command,&params,|_,_,_|{calls+=1;panic!("Job refusal read source")}).unwrap_err()};assert_eq!(error,photocraft_engine::EngineError::Disabled(command.into(),expected).to_string());assert_eq!(calls,0);unchanged(&f.engine,&before);release.store(true,Ordering::SeqCst);f.engine.wait_job(job).unwrap();}
}
